// Package builtinproto is the demi.builtin package's contract
// (docs/architecture/crates-and-packages.md § builtin-protocol): the arguments
// and results of its file.* and browser.* operations. It holds types and their
// checks only; the operations, the transport and the IO live in
// builtincommands.
//
// Every type is a wire type, declared here and generated by cmd/wiregen: a value
// that enters the process is decoded into its type and checked where it enters
// ([Parse]), and the JSON Schema of each operation's input and result is
// generated with it (the functions named ...Schema).
package builtinproto

//go:generate go run github.com/wspl/demi/go/cmd/wiregen

import (
	"errors"
	"fmt"
	"slices"

	"github.com/wspl/demi/go/internal/wire"
)

// InvalidError says that a value breaks the rules of its type: it names the
// field and the rule, never the value.
type InvalidError = wire.InvalidError

// Package is the package's id, which its release descriptor names and the
// coding agent's commands bind to.
const Package = "demi.builtin"

// The operations that are not the file's or the browser's.
const (
	// LiveOperation is the declared operation that serves a view.
	LiveOperation = "browser.live"
)

// ErrUnknownOperation is the error of an operation that the package does not
// serve.
var ErrUnknownOperation = errors.New("unknown operation")

// Parse decodes the arguments of the operation named name, and checks them. It
// returns the operation's input: [ReadArgs], [CreateArgs], [EditArgs] or
// [PatchArgs] for a file operation, a [BrowserInput] such as [OpenInput] for a
// browser operation, or [LiveInput] for the live view. A name the package does
// not serve is refused with [ErrUnknownOperation]; any other failure is an
// *[InvalidError] that names the field and the rule, never the value.
func Parse(name string, args []byte) (any, error) {
	decode, ok := decoders[name]
	if !ok {
		return nil, fmt.Errorf("%w %s", ErrUnknownOperation, name)
	}
	return decode(args)
}

// Operations returns every operation the package serves, as its descriptor
// lists them: the file operations, the browser operations and the live view.
func Operations() []string {
	return slices.Clone(operationOrder)
}
